class TestVisiumHDSplittingBarcodeDetector:
    """Test Visium HD splitting barcode detector on synthetic concatenated reads."""

    R1 = "CTACACGACGCTCTTCCGATCT"
    TSO_TAIL = "ATGTACTCTGCGTTGATACCACTGCTT"
    CDNA = ("GCTAGCATCGATCGGATCCAGTACGTAGCTAGGCTAACGTAGGCATGCAAGTCGACGTAGCATGCAGTCAGTACGATCGATGCATGCAGT" * 3)
    # (BC1, BC2, UMI) per molecule, barcodes from VISIUM_HD_BC1/BC2_WHITELIST
    MOLECULES = [
        ("GTCACTATACTGCAAG", "AAGATCATGTGCAAG", "ACGTACGTA"),
        ("GCTTAAATGCATCAG", "CTGATCAGCGCGAAG", "TTGCAGCAT"),
        ("GTCTTGTGTGCGCACG", "TAGATGGCAGCCAG", "CAGGATCCA"),
    ]

    @staticmethod
    def _detector():
        return VisiumHDSplittingBarcodeDetector([VISIUM_HD_BC1_WHITELIST, VISIUM_HD_BC2_WHITELIST])

    def _molecule(self, index, tso_prefix="", r1=None, polyt_len=30):
        """One molecule in barcode-first orientation: R1 UMI BC1 BC2 VV polyT cDNA TSO."""
        bc1, bc2, umi = self.MOLECULES[index]
        r1 = self.R1 if r1 is None else r1
        return r1 + umi + bc1 + bc2 + "GC" + "T" * polyt_len + self.CDNA + tso_prefix + self.TSO_TAIL

    def _concat_read(self, strands):
        parts = []
        for i, strand in enumerate(strands):
            mol = self._molecule(i)
            parts.append(mol if strand == "+" else reverese_complement(mol))
        return "".join(parts)

    @staticmethod
    def _detections(result):
        return sorted((p.get_barcode(), p.get_umi(), p.strand) for p in result.detected_patterns)

    def _expected(self, strands):
        return sorted((bc1 + "|" + bc2, umi, strand)
                      for (bc1, bc2, umi), strand in zip(self.MOLECULES, strands))

    def test_init(self):
        detector = self._detector()
        assert detector.TSO == self.TSO_TAIL
        assert not detector.tso_indexer.empty()

    def test_no_match_random_sequence(self):
        result = self._detector().find_barcode_umi("test_read", RANDOM_SEQUENCE)
        assert isinstance(result, SplittingBarcodeDetectionResult)
        assert not result.is_valid()

    @pytest.mark.parametrize("strands", ["++", "+-", "-+", "--", "+-+", "-+-"])
    def test_concatenated_molecules(self, strands):
        result = self._detector().find_barcode_umi("test_read", self._concat_read(strands))
        assert self._detections(result) == self._expected(strands)
        for p in result.detected_patterns:
            assert isinstance(p, VisiumHDSplitBarcodeDetectionResult)

    @pytest.mark.parametrize("tso_prefix", ["", "CCC"])
    def test_tso_detected_with_and_without_ccc(self, tso_prefix):
        first = self._molecule(0, tso_prefix)
        read = first + self._molecule(1)
        result = self._detector().find_barcode_umi("test_read", read)
        assert len(result.detected_patterns) == 2
        first_pattern = min(result.detected_patterns, key=lambda p: p.polyT)
        assert first_pattern.tso == len(first) - len(self.TSO_TAIL)

    def test_internal_molecule_without_r1(self):
        """Barcodes are read backwards from polyT, so a molecule with a destroyed R1 is still found."""
        first = self._molecule(0)
        read = first + self._molecule(1, r1="GATCGATCGATCGATCGATCGA")
        result = self._detector().find_barcode_umi("test_read", read)
        assert self._detections(result) == self._expected("++")
        second = max(result.detected_patterns, key=lambda p: p.polyT)
        assert second.r1 == -1
        # the segment starts where R1 would end, not at the read start
        assert second.get_fasta_segment_start() >= len(first)

    def test_short_polyt_found_near_r1(self):
        """A polyT too short for the default search is looked for right after the barcodes."""
        read = self._molecule(0, polyt_len=8) + self._molecule(1)
        result = self._detector().find_barcode_umi("test_read", read)
        assert self._detections(result) == self._expected("++")

    def test_segments_do_not_overlap(self):
        read = self._concat_read("+++")
        result = self._detector().find_barcode_umi("test_read", read)
        patterns = sorted(result.detected_patterns, key=lambda p: p.get_fasta_segment_start())
        assert len(patterns) == 3
        for prev, curr in zip(patterns, patterns[1:]):
            assert prev.get_fasta_segment_end(len(read)) <= curr.get_fasta_segment_start()

    @pytest.mark.parametrize("read_sequence, true_barcode, true_umi", VISIUM_HD_READS)
    def test_real_reads_give_single_molecule(self, read_sequence, true_barcode, true_umi):
        """Single-molecule reads are detected as by the non-splitting detector, on the + strand."""
        result = self._detector().find_barcode_umi("test_read", read_sequence)
        assert len(result.detected_patterns) == 1
        pattern = result.detected_patterns[0]
        assert pattern.get_barcode() == true_barcode
        assert pattern.get_umi() == true_umi
        assert pattern.strand == "+"

    def test_fallback_sets_strand_without_polyt(self):
        # barcode region prefix without polyT, reverse-complemented
        read_sequence, true_barcode, _ = VISIUM_HD_READS[3]
        result = self._detector().find_barcode_umi("test_read", reverese_complement(read_sequence))
        assert len(result.detected_patterns) == 1
        assert result.detected_patterns[0].get_barcode() == true_barcode
        assert result.detected_patterns[0].strand == "-"

    def test_pickle_round_trip(self):
        import pickle
        detector = pickle.loads(pickle.dumps(self._detector()))
        result = detector.find_barcode_umi("test_read", self._concat_read("+-"))
        assert self._detections(result) == self._expected("+-")

    def test_header(self):
        assert "tso_start" in VisiumHDSplittingBarcodeDetector.header()

    def test_split_fasta_segment_without_polyt(self, tmp_path):
        """The FASTA segment of a read without polyT is cut from the read itself, named with its strand."""
        from Bio import SeqIO
        from isoquant_lib.barcode_calling.detect_barcodes import BarcodeCaller
        read_sequence, true_barcode, _ = VISIUM_HD_READS[3]
        fasta = str(tmp_path / "split.fa")
        caller = BarcodeCaller(str(tmp_path / "barcodes.tsv"), self._detector(),
                               output_sequences=fasta, split_reads=True)
        caller._process_read_split("read1", read_sequence)
        caller.close()
        records = list(SeqIO.parse(fasta, "fasta"))
        assert len(records) == 1
        assert records[0].id.startswith("read1_") and records[0].id.endswith("_+")
        assert str(records[0].seq) in read_sequence


class TestVisiumHDMultiplexedSplittingBarcodeDetector(TestVisiumHDSplittingBarcodeDetector):
    """Units between ONT sample barcodes: ADAPTER BARCODE [Visium molecules] BARCODErc ADAPTERrc."""

    @staticmethod
    def _detector():
        return VisiumHDMultiplexedSplittingBarcodeDetector([VISIUM_HD_BC1_WHITELIST, VISIUM_HD_BC2_WHITELIST])

    @staticmethod
    def _unit(sample, molecules):
        adapter = VisiumHDMultiplexedSplittingBarcodeDetector.ADAPTER_TOP
        left, right = VisiumHDMultiplexedSplittingBarcodeDetector.SAMPLE_BARCODES[sample]
        return (adapter + "AAGGTTAA" + left + "CAGCACCT" + "".join(molecules) +
                "AGGTGCTG" + right + "TTAACCTT" + reverese_complement(adapter))

    def test_units_and_samples(self):
        read = self._unit("A1", [self._molecule(0)]) + self._unit("D1", [reverese_complement(self._molecule(1))])
        result = self._detector().find_barcode_umi("read", read)
        found = sorted((p.unit, p.get_barcode(), p.strand, p.sample_left, p.sample_right)
                       for p in result.detected_patterns)
        bc = [bc1 + "|" + bc2 for bc1, bc2, _ in self.MOLECULES]
        assert found == [(0, bc[0], "+", "A1", "A1rc"), (1, bc[1], "-", "D1", "D1rc")]
        # FASTA segments stay within their unit
        for p in result.detected_patterns:
            assert p.unit_start <= p.get_fasta_segment_start() < p.get_fasta_segment_end(len(read)) <= p.unit_end

    def test_several_molecules_in_one_unit(self):
        read = self._unit("D1", [self._molecule(0), self._molecule(1)])
        result = self._detector().find_barcode_umi("read", read)
        assert [(p.unit, p.sample_left, p.sample_right) for p in result.detected_patterns] == \
            [(0, "D1", "D1rc"), (0, "D1", "D1rc")]

    def test_header(self):
        assert VisiumHDMultiplexedSplittingBarcodeDetector.header().endswith("\tunit\tsample_left\tsample_right")


